import{_ as t,o as s,c as a,a0 as i}from"./chunks/framework.ysVzM4be.js";const k=JSON.parse('{"title":"Getting Started","description":"Start the control plane with npx, and shape the Default configuration to your workflow.","frontmatter":{"title":"Getting Started","description":"Start the control plane with npx, and shape the Default configuration to your workflow."},"headers":[],"relativePath":"getting-started/index.md","filePath":"getting-started/index.md"}'),n={name:"getting-started/index.md"};function o(l,e,h,r,p,d){return s(),a("div",null,[...e[0]||(e[0]=[i(`<h1 id="getting-started" tabindex="-1">Getting Started <a class="header-anchor" href="#getting-started" aria-label="Permalink to &quot;Getting Started&quot;">​</a></h1><p>The control plane ships through npm. You install nothing: <code>npx</code> runs the current published version, and the first start writes the config file that the rest of this guide edits.</p><h2 id="requirements" tabindex="-1">Requirements <a class="header-anchor" href="#requirements" aria-label="Permalink to &quot;Requirements&quot;">​</a></h2><ul><li>Node <code>26.4.0</code> or newer. Below the floor the start fails with the required version and the reason: the OpenTUI renderer loads <code>node:ffi</code>, which Node gates behind <code>--experimental-ffi</code>.</li><li><a href="https://github.com/seriousjul/herdr" target="_blank" rel="noreferrer">herdr</a> on the <code>PATH</code>. The control plane drives it through its CLI and never starts an agent process itself.</li><li>The agent CLI of each agent type you use, with its own provider auth applied.</li></ul><h2 id="start-the-control-plane" tabindex="-1">Start the control plane <a class="header-anchor" href="#start-the-control-plane" aria-label="Permalink to &quot;Start the control plane&quot;">​</a></h2><p>Run either name; both start the same app:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my-little-software-factory</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mlsf</span></span></code></pre></div><p>On the first start the app finds no config file, writes the <a href="#the-config-file">Default configuration</a> to <code>~/.config/my-little-software-factory/config.toml</code>, and says so on the start lines before the interface appears. The start lines name the path, so you know where to edit.</p><p>A second start reads the file. A line that does not parse or does not validate stops the start with one readable error line. A present file must carry every required key, and a key the control plane does not read is an error, so a typo surfaces at the start, not at handoff time.</p><h2 id="the-config-file" tabindex="-1">The Config file <a class="header-anchor" href="#the-config-file" aria-label="Permalink to &quot;The Config file&quot;">​</a></h2><p>The config lives at:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>~/.config/my-little-software-factory/config.toml</span></span></code></pre></div><p>or at the path the <code>--config</code> flag names:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my-little-software-factory</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /path/to/config.toml</span></span></code></pre></div><p>The state file lives at:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>~/.local/state/my-little-software-factory/state.sqlite</span></span></code></pre></div><p>or at the path <code>$XDG_STATE_HOME/my-little-software-factory/state.sqlite</code> when the environment sets it, or at the path the <code>state-file</code> key names when the config sets one.</p><p>The shipped Default configuration carries a working control plane and the parts it cannot know about your machine: no ticket sources, no repository mappings, and no <code>state-file</code> key. Everything else is on: the <code>pi</code>, <code>codex</code>, and <code>claude</code> agent types, the four workflow task types, the three task rules, and one <code>consult</code> Consultation type that passes your input straight through. The <a href="https://github.com/SeriousJul/my-little-software-factory/blob/main/README.md#key-reference" target="_blank" rel="noreferrer">README key reference</a> names every key, its default, and what it does.</p><h2 id="add-a-ticket-source" tabindex="-1">Add a ticket source <a class="header-anchor" href="#add-a-ticket-source" aria-label="Permalink to &quot;Add a ticket source&quot;">​</a></h2><p>The Default configuration holds a commented-out source block where you add your own. Unmark it and edit the <code>repositories</code> list to your <code>owner/name</code> values:</p><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sources</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">name = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;issues&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">kind = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;github-issues&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">refresh-interval-seconds = </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">60</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">repositories = [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;owner/name&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;owner/other&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span></code></pre></div><p>The <code>name</code> is what the interface shows. The <code>kind</code> is <code>github-issues</code> or <code>github-pull-requests</code>. The <code>refresh-interval-seconds</code> sets how often the control plane refreshes the source. The source reads the labels on each ticket; <a href="./../labels.html">docs/labels.md</a> names what each label means to the control plane.</p><p>Repository checkout paths live in the <code>repos</code> table, one key per <code>owner/name</code>:</p><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">repos</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&quot;owner/name&quot; = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;~/src/name&quot;</span></span></code></pre></div><h2 id="extend-the-workflow-template" tabindex="-1">Extend the workflow template <a class="header-anchor" href="#extend-the-workflow-template" aria-label="Permalink to &quot;Extend the workflow template&quot;">​</a></h2><p>The task types and task rules of the Default configuration form the workflow template, and the file marks them as meant to be extended. The template carries the four task types <code>implement</code>, <code>review</code>, <code>rework</code>, and <code>merge</code>, and the three rules of the label workflow:</p><table tabindex="0"><thead><tr><th>Rule</th><th>When</th><th>Task type</th></tr></thead><tbody><tr><td>1</td><td>A pull request carries the <code>needs-work</code> label.</td><td><code>rework</code></td></tr><tr><td>2</td><td>A pull request carries the <code>ready-for-review</code> label.</td><td><code>review</code></td></tr><tr><td>3</td><td>A pull request carries the <code>ready-to-ship</code> label.</td><td><code>merge</code></td></tr></tbody></table><p>Add your own task type with a <code>[task-types.&lt;name&gt;]</code> table. The <code>template</code> carries the prompt body, and the <code>{placeholders}</code> name the ticket facts the control plane fills in. Add a rule that routes a ticket to it:</p><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">task-types</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">my-type</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">template = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;My prompt for {title}.&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">task-rules</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">task-type = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;my-type&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">task-rules</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">when</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">source-kind = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;github-pull-request&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">labels-any = [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;my-label&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span></code></pre></div><p>The rules run in file order, and the first match wins. A ticket no rule matches takes the <code>default-task-type</code>.</p>`,30)])])}const u=t(n,[["render",o]]);export{k as __pageData,u as default};
